public class DBTraceBookmarkSpace : TraceBookmarkSpace, DBTraceSpaceBased {
	protected DBTraceBookmarkManager manager;
	protected ReadWriteLock @lock;
	protected DBTrace trace;
	protected AddressSpace space;

	protected DBTraceAddressSnapRangePropertyMapSpace<DBTraceBookmark, DBTraceBookmark> bookmarkMapSpace;
	protected DBCachedObjectIndex<string, DBTraceBookmark> bookmarksByTypeName;
	protected Collection<DBTraceBookmark> bookmarkView;

	public DBTraceBookmarkSpace(DBTraceBookmarkManager manager, AddressSpace space)
    {
		this.manager = manager;
		this.@lock = manager.getLock();
		this.trace = manager.getTrace();
		this.space = space;

		this.bookmarkMapSpace =
			new(DBTraceBookmark.tableName(space), trace,
				trace.getStoreFactory(), @lock, space, typeof(DBTraceBookmark),
				(t, s, r) => new DBTraceBookmark(this, t, s, r));
		this.bookmarksByTypeName =
			bookmarkMapSpace.getUserIndex(typeof(string), DBTraceBookmark.TYPE_COLUMN);
		this.bookmarkView = Collections.unmodifiableCollection(bookmarkMapSpace.values());
	}

	/* @Override */
	public Trace getTrace() {
		return trace;
	}

	/* @Override */
	public AddressSpace getAddressSpace() {
		return space;
	}

	protected DBTraceBookmarkType assertInTrace(TraceBookmarkType type) {
		if (!(type is DBTraceBookmarkType)) {
			throw new IllegalArgumentException("Given type is not part of this trace");
		}
		DBTraceBookmarkType dbType = (DBTraceBookmarkType) type;
		if (dbType.manager != manager) {
			throw new IllegalArgumentException("Given type is not part of this trace");
		}
		return dbType;
	}

	/* @Override */
	public Set<string> getCategoriesForType(TraceBookmarkType type) {
		assertInTrace(type);
		using (LockHold hold = LockHold.@lock(@lock.readLock()))
{
			Set<string> result = new();
			foreach (DBTraceBookmark bookmark in bookmarksByTypeName.get(type.getTypeString())) {
				result.add(bookmark.getCategory());
			}
			return result;
		}
	}

